mapper.select:
SELECT id, order_id as orderId, merchant_id as merchantId, tag_name as tagName, 
       tag_color as tagColor, create_time as createTime
FROM order_tag WHERE id = #{id}

SELECT tag_name as tagName, tag_color as tagColor, COUNT(*) as count
FROM order_tag WHERE merchant_id = #{merchantId}
GROUP BY tag_name, tag_color ORDER BY count DESC
